<script setup lang="ts">import{onMounted,ref}from'vue';import PageHeader from'../../components/PageHeader.vue';import{client,errorMessage,requireData}from'../../../shared/api/client';import type{components}from'../../../shared/api/schema.gen';const values=ref<components['schemas']['TranslationProgress'][]>([]);const error=ref('');onMounted(async()=>{try{values.value=requireData(await client.GET('/api/admin/translations/status'))}catch(cause){error.value=errorMessage(cause)}})</script>
<template><PageHeader title="翻译进度"/><p v-if="error" class="text-danger">{{ error }}</p><article v-for="value in values" :key="value.language" class="mb-3 rounded-card border border-border p-4"><strong>{{ value.language }}</strong><progress :value="value.percent" max="100" class="mx-4"/><span>{{ value.translated }}/{{ value.total }}，待复核 {{ value.needsReview }}</span></article></template>
